"""POSIX-style word splitting with quoting and no expansions. See task.md."""

from __future__ import annotations


class SplitError(ValueError):
    """Raised for an unterminated quote or a lone trailing backslash."""


def split(line: str) -> list[str]:
    """Split `line` into words. See task.md for the rules."""
    words = []
    current_word = []
    i = 0
    in_single_quote = False
    in_double_quote = False
    word_open = False

    while i < len(line):
        char = line[i]

        # Handle single quotes - everything is literal
        if in_single_quote:
            if char == "'":
                in_single_quote = False
            else:
                current_word.append(char)
            i += 1

        # Handle double quotes - some escapes are processed
        elif in_double_quote:
            if char == '"':
                in_double_quote = False
                i += 1
            elif char == "\\" and i + 1 < len(line):
                next_char = line[i + 1]
                if next_char in ("$", "`", '"', "\\"):
                    # Backslash followed by special char - drop backslash
                    current_word.append(next_char)
                    i += 2
                elif next_char == "\n":
                    # Line continuation - both chars vanish
                    i += 2
                else:
                    # Backslash is literal before other chars
                    current_word.append(char)
                    i += 1
            else:
                current_word.append(char)
                i += 1

        # Outside quotes
        else:
            if char == "'":
                # Start single quote - opens word
                word_open = True
                in_single_quote = True
                i += 1
            elif char == '"':
                # Start double quote - opens word
                word_open = True
                in_double_quote = True
                i += 1
            elif char == "\\":
                if i + 1 < len(line):
                    next_char = line[i + 1]
                    if next_char == "\n":
                        # Line continuation - doesn't open word
                        i += 2
                    else:
                        # Escape the next character - opens word
                        word_open = True
                        current_word.append(next_char)
                        i += 2
                else:
                    # Trailing backslash error
                    raise SplitError("Lone trailing backslash")
            elif char in (" ", "\t"):
                # Separator - closes current word
                if word_open:
                    words.append("".join(current_word))
                    current_word = []
                    word_open = False
                i += 1
            elif char == "#" and not word_open:
                # Comment at start of word - discard rest of line
                break
            else:
                # Regular character - opens word
                word_open = True
                current_word.append(char)
                i += 1

    # Check for unclosed quotes
    if in_single_quote or in_double_quote:
        raise SplitError("Unterminated quote")

    # Add final word if open
    if word_open:
        words.append("".join(current_word))

    return words
